class Solution:
    def minSubArrayLen(self, target: int, nums: List[int]) -> int:
        if sum(nums) < target:
            return 0
        n = len(nums)
        ans = n
        cur_sum = nums[0]
        right = 0
        for left in range(n):
            while right + 1 < n and cur_sum < target:
                cur_sum += nums[right + 1]
                right += 1
            if cur_sum >= target:
                ans = min(ans, right - left + 1)
                cur_sum -= nums[left]
            else:
                break
        return ans
